import{_ as a,o as t,c as r,ag as s}from"./chunks/framework.BGkQCay2.js";const m=JSON.parse('{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/benchmarks.md","filePath":"guide/benchmarks.md"}'),n={name:"guide/benchmarks.md"};function i(o,e,d,h,c,l){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h1><p>This page describes how to benchmark Vex. It does not publish performance numbers: the current compiler and runtime are still changing, and unsupported or unrepeatable measurements would be misleading.</p><h2 id="benchmarking-a-program" tabindex="-1">Benchmarking a program <a class="header-anchor" href="#benchmarking-a-program" aria-label="Permalink to &quot;Benchmarking a program&quot;">​</a></h2><p>Start with a checked program and keep the workload, compiler version, target, optimization settings, and input data under version control.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark.vx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmark.vx</span></span></code></pre></div><p>Use the repository&#39;s test and benchmark tooling only when the command is present in the compiler version being evaluated. Run several warm-up and measurement iterations, and report a distribution rather than a single fastest result.</p><h2 id="what-to-record" tabindex="-1">What to record <a class="header-anchor" href="#what-to-record" aria-label="Permalink to &quot;What to record&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td>Compiler</td><td><code>vex 0.4.0-rc.39</code></td></tr><tr><td>Commit</td><td>Short repository revision</td></tr><tr><td>Target</td><td>OS, architecture, and runtime configuration</td></tr><tr><td>Workload</td><td>Source revision, input size, and expected result</td></tr><tr><td>Build mode</td><td>Exact command and optimization flags</td></tr><tr><td>Measurement</td><td>Iteration count, warm-up policy, median, and spread</td></tr></tbody></table><p>Comparisons with Rust, Go, Zig, C, or C++ are meaningful only when each implementation performs the same work and the results can be reproduced from published source. Do not present estimates as measurements or infer production readiness from a benchmark.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>SIMD, async, channels, GPU backends, and standard-library services are not uniform across platforms. A successful <code>vex lint</code> proves semantic acceptance; it does not prove that fused backend codegen, native linking, I/O, or a selected accelerator works on the target machine. See the <a href="/docs/guide/language-status">language status</a> page for current limitations.</p>`,11)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
